import { CSPProvider } from "@/registry/erbium/ui/csp-provider";
import { SkeletonProvider } from "@/registry/erbium/ui/skeleton";
import { Toaster } from "@/registry/erbium/ui/toast";
import { cn } from "@/registry/erbium/lib/erbium-utils";
import type { ReactNode } from "react";

export const ShowcaseProviders = ({
  children,
  toast = false,
}: {
  children?: ReactNode;
  toast?: boolean;
}) => (
  <CSPProvider disableStyleElements>
    <SkeletonProvider>
      {children}
      {toast && <Toaster />}
    </SkeletonProvider>
  </CSPProvider>
);

/**
 * The box an example renders in. Inline it is capped to the reading width; with `fill` (a
 * full-screen slide) it takes the whole panel, so an example sized from its container (`w-full`,
 * `h-full` with a minimum) grows with it, while one with a natural size stays centred.
 */
export const ShowcaseSurface = ({
  children,
  fill = false,
}: {
  children?: ReactNode;
  fill?: boolean;
}) => (
  <div
    data-slot="component-preview"
    className={cn(
      "relative isolate mx-auto flex w-full min-w-0 items-center justify-center gap-section p-5 font-sans text-foreground contain-layout sm:p-8 [&>.min-w-72.max-w-2xl]:flex [&>.min-w-72.max-w-2xl]:flex-col [&>.min-w-72.max-w-2xl]:items-center [&>.min-w-72.max-w-2xl]:justify-center",
      fill ? "flex-1" : "min-h-64 max-w-3xl",
    )}
  >
    {children}
  </div>
);

import { Radio } from "@base-ui/react/radio";
import { RadioGroup } from "@base-ui/react/radio-group";
import { SegmentedControl, SegmentedControlItem } from "@/registry/erbium/ui/segmented-control";

export default function SegmentedControlDemoExample() {
  return (
    <SegmentedControl aria-label="Billing period" render={<RadioGroup defaultValue="monthly" />}>
      <SegmentedControlItem render={<Radio.Root value="monthly" />}>Monthly</SegmentedControlItem>
      <SegmentedControlItem render={<Radio.Root value="yearly" />}>Yearly</SegmentedControlItem>
      <SegmentedControlItem render={<Radio.Root value="lifetime" />}>Lifetime</SegmentedControlItem>
    </SegmentedControl>
  );
}

import { Toggle } from "@base-ui/react/toggle";
import { ToggleGroup } from "@base-ui/react/toggle-group";
import { SegmentedControl, SegmentedControlItem } from "@/registry/erbium/ui/segmented-control";

export default function SegmentedControlFilterExample() {
  return (
    <SegmentedControl render={<ToggleGroup aria-label="Issue status" defaultValue={["open"]} />}>
      <SegmentedControlItem render={<Toggle value="open" />}>Open</SegmentedControlItem>
      <SegmentedControlItem render={<Toggle value="closed" />}>Closed</SegmentedControlItem>
      <SegmentedControlItem render={<Toggle value="draft" />}>Draft</SegmentedControlItem>
    </SegmentedControl>
  );
}

import { CodeBlock } from "@/registry/erbium/blocks/code-block";
import { Form, useAppForm } from "@/registry/erbium/ui/form";

const plans = [
  { label: "Starter", value: "starter" },
  { label: "Team", value: "team" },
  { label: "Enterprise", value: "enterprise" },
] as const;

export default function SegmentedControlFormExample() {
  const form = useAppForm({ defaultValues: { plan: "" } });

  return (
    <Form form={form} className="flex w-80 flex-col gap-group">
      <form.AppField
        name="plan"
        validators={{ onDynamic: ({ value }) => (value ? undefined : "Choose a plan.") }}
      >
        {(field) => (
          <field.SegmentedField
            label="Plan"
            description="You can change plans at any time."
            options={plans}
            required
          />
        )}
      </form.AppField>
      <form.SubmitButton className="self-start">Continue</form.SubmitButton>
      <form.Subscribe
        selector={(state) =>
          state.isSubmitSuccessful && !state.isSubmitting ? state.values : undefined
        }
      >
        {(values) =>
          values && (
            <CodeBlock
              code={JSON.stringify(values, null, 2)}
              language="json"
              title="Submitted values"
            />
          )
        }
      </form.Subscribe>
    </Form>
  );
}

import { useState } from "react";
import { SegmentedControl, SegmentedControlItem } from "@/registry/erbium/ui/segmented-control";

const sections = [
  { href: "#overview", label: "Overview" },
  { href: "#activity", label: "Activity" },
  { href: "#settings", label: "Settings" },
];

export default function SegmentedControlNavigationExample() {
  // A router would derive the current link from the location instead.
  const [current, setCurrent] = useState("#overview");

  return (
    <SegmentedControl aria-label="Project sections" render={<nav />}>
      {sections.map((section) => (
        <SegmentedControlItem
          key={section.href}
          render={
            <a
              href={section.href}
              aria-current={section.href === current ? "page" : undefined}
              onClick={() => {
                setCurrent(section.href);
              }}
            >
              {section.label}
            </a>
          }
        />
      ))}
    </SegmentedControl>
  );
}

